import React from 'react';

// Icon component for the logo
const IconLeaf = (props) => (
  <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="lucide lucide-leaf">
    <path d="M11 20A7 7 0 0 1 9.85 15.3l-1.42-1.42a4 4 0 0 0-.84 4.51c-.68 1.4-1.9 2.1-3.14 2.1-1 0-1.87-.27-2.7-.87 1.25.75 2.5 1.15 3.84 1.15 3.5 0 6-3.72 6-8s-2.5-8-6-8c-1.34 0-2.59.4-3.84 1.15.83-.6 1.7-.87 2.7-.87 1.24 0 2.46.7 3.14 2.1a4 4 0 0 0 .84 4.51l1.42 1.42A7 7 0 0 1 11 20z"/>
    <path d="M19 14c1.47 0 2.91.48 4 1.41-1.09-.93-2.53-1.41-4-1.41z"/>
  </svg>
);

const Logo3D = () => (
  <h1
    className="text-3xl sm:text-4xl font-black z-20 cursor-pointer flex items-center gap-2"
    style={{
      textShadow: '2px 2px 0 #15803d, 4px 4px 0 #059669, 6px 6px 0 #065f46',
      letterSpacing: '1px',
    }}
  >
    <IconLeaf 
      className="w-8 h-8 text-green-400 transition-transform duration-500 hover:rotate-12 hover:scale-110"
      style={{ filter: 'drop-shadow(2px 2px 0 #065f46)' }}
    />
    <span className="bg-gradient-to-r from-green-400 via-green-600 to-green-500 bg-clip-text text-transparent">
      EcoPackAI
    </span>
  </h1>
);

const FontLoader = () => (
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap" rel="stylesheet" />
);

export default function HomePage() {
  return (
    <>
      <FontLoader />

      <style>{`
        @keyframes floatBlob {
          0%, 100% { transform: translateY(0) scale(1); }
          50% { transform: translateY(-20px) scale(1.05); }
        }
        .animate-float { animation: floatBlob 15s ease-in-out infinite; }

        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .fadeInUp { animation: fadeInUp 1s ease-out forwards; }
        .fadeInUp-delay-1 { animation: fadeInUp 1s ease-out forwards 0.3s; }
        .fadeInUp-delay-2 { animation: fadeInUp 1s ease-out forwards 0.6s; }

        .gradient-btn {
          background: linear-gradient(to right, #16a34a, #22c55e, #16a34a);
          background-size: 200% 200%;
          transition: all 0.4s ease-in-out;
        }
        .gradient-btn:hover {
          background-position: right center;
          transform: scale(1.05);
        }
      `}</style>

      <div className="relative min-h-screen flex flex-col bg-gradient-to-br from-green-50 via-white to-green-100 text-gray-800 font-['Inter'] overflow-hidden">
        {/* Animated Background Blobs */}
        <div className="absolute top-10 left-0 w-80 h-80 bg-green-300 rounded-full mix-blend-multiply filter blur-3xl opacity-40 animate-float"></div>
        <div className="absolute bottom-10 right-0 w-96 h-96 bg-emerald-400 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-float"></div>

        {/* Navbar */}
        <header className="flex justify-between items-center px-10 py-6 z-10 relative">
          <Logo3D />
          <nav className="space-x-6 text-lg font-medium">
            {['About', 'Features', 'Contact'].map((item) => (
              <a key={item} href={`#${item.toLowerCase()}`} className="hover:text-green-600 transition-all duration-300">{item}</a>
            ))}
          </nav>
        </header>

        {/* Hero Section */}
        <section className="flex flex-col justify-center items-center text-center mt-24 px-6 z-10">
          <h2 className="text-5xl sm:text-6xl font-extrabold text-green-800 fadeInUp">EcoPackAI</h2>
          <p className="mt-4 text-xl sm:text-2xl text-gray-700 max-w-2xl fadeInUp-delay-1">
            AI-Powered Sustainable Packaging Recommendations
          </p>
          <div className="mt-8 fadeInUp-delay-2">
            <button className="gradient-btn text-white px-10 py-3 text-lg font-semibold rounded-full shadow-lg">
              Get Started
            </button>
          </div>
        </section>

        {/* About Section */}
        <section id="about" className="py-24 px-10 text-center bg-white/60 backdrop-blur-sm mt-16 rounded-xl mx-6">
          <h3 className="text-3xl font-bold text-green-700 mb-6">About EcoPackAI</h3>
          <p className="max-w-3xl mx-auto text-lg text-gray-700">
            EcoPackAI helps businesses choose eco-friendly, cost-effective packaging materials 
            using AI-driven recommendations. Our mission is to reduce carbon footprints and promote 
            sustainable packaging decisions across industries.
          </p>
        </section>

        {/* Features Section */}
        <section id="features" className="py-20 px-8 bg-green-50 text-center">
          <h3 className="text-3xl font-bold text-green-700 mb-10">Key Features</h3>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10 max-w-6xl mx-auto">
            {[
              { title: "AI-Powered Insights", desc: "Smart algorithms recommend sustainable & cost-efficient packaging materials." },
              { title: "Eco Material Database", desc: "Access verified data on 20+ biodegradable and recyclable materials." },
              { title: "Visual Dashboards", desc: "Compare cost vs. CO₂ footprint with easy-to-read charts & exports." },
              { title: "Sustainability Impact", desc: "Achieve up to 30% reduction in environmental impact per packaging choice." },
            ].map((f, i) => (
              <div key={i} className="p-6 bg-white shadow-lg rounded-2xl transition-all duration-300 hover:shadow-2xl hover:scale-105 hover:bg-green-50">
                <h4 className="text-2xl font-semibold text-green-700 mb-2">{f.title}</h4>
                <p className="text-gray-600">{f.desc}</p>
              </div>
            ))}
          </div>
        </section>

        {/* Call To Action */}
        <section className="py-20 bg-green-600 text-white text-center">
          <h3 className="text-3xl font-bold mb-6 transition duration-700">Ready to make packaging sustainable?</h3>
          <button className="bg-white text-green-700 px-8 py-3 text-lg font-semibold rounded-full shadow-md transition hover:bg-gray-100 hover:scale-110">
            Get Started
          </button>
        </section>

        {/* Footer */}
        <footer id="contact" className="py-6 bg-green-900 text-white text-center text-sm">
          © {new Date().getFullYear()} EcoPackAI | Designed with 💚 for a greener planet
        </footer>
      </div>
    </>
  );
}
